<script setup lang="ts">
import { computed,ref } from 'vue'
import ExploreFrame from './ExploreFrame.vue'
import ArtPicture from './ArtPicture.vue'
import { useExperience } from './use-experience'
import { eraseArt,artInspirations,addArt,artBackgrounds,artColors,artStamps,loadArtwork,saveArtwork,setArtBackground,type ArtMark,type ArtPoint } from './creative-studio'
const props=defineProps<{storageKey?:string}>()
const {save,frame,feedback,resetOpen,act,undo,requestReset,reset,hint,onStop}=useExperience(props,'creative-studio')
const round=computed(()=>save.value.round),tool=ref('brush'),color=ref(artColors[0]),width=ref(8),picture=ref<InstanceType<typeof ArtPicture>|null>(null),preview=ref<ArtMark|null>(null),exporting=ref(false)
let pointer=-1
const rules=['选择画笔和颜色，在画纸上拖动绘画；也可以选择印章，点一下盖出图案。','可以换画纸、撤回笔画。保存作品后仍能继续画，最近十二幅作品留在本机小画廊。','点击“导出图片”下载 PNG；画作只保存在当前浏览器，不上传到服务器。']
function point(event:PointerEvent):ArtPoint {const box=picture.value!.element!.getBoundingClientRect();return [Math.round(Math.max(0,Math.min(600,(event.clientX-box.left)/box.width*600))),Math.round(Math.max(0,Math.min(400,(event.clientY-box.top)/box.height*400)))]}
function start(event:PointerEvent){if(event.button!==0 || !event.isPrimary)return;event.preventDefault();if(tool.value==='eraser'){const [x,y]=point(event);if(act(()=>eraseArt(round.value,x,y)))feedback.value='已擦除这一笔，其他笔画保留。';else feedback.value='点一下要擦除的笔画或印章。';return}if(round.value.marks.length>=64){feedback.value='这张画纸已有 64 笔，可以保存后换一张新画纸。';return}const [x,y]=point(event);if(tool.value==='brush'){pointer=event.pointerId;picture.value!.element!.setPointerCapture(pointer);preview.value={kind:'stroke',points:[[x,y]],width:width.value,color:color.value}}else act(()=>addArt(round.value,{kind:'stamp',stamp:tool.value,x,y,size:72,color:color.value}))}
function move(event:PointerEvent){if(pointer!==event.pointerId || preview.value?.kind!=='stroke')return;event.preventDefault();const next=point(event),points=preview.value.points,last=points[points.length-1];if(Math.hypot(next[0]-last[0],next[1]-last[1])<3)return;if(points.length<128)points.push(next);else points[points.length-1]=next}
function end(event:PointerEvent){if(pointer!==event.pointerId || !preview.value)return;const mark=preview.value;preview.value=null;pointer=-1;try{picture.value!.element!.releasePointerCapture(event.pointerId)}catch{/* 浏览器可能已释放触点。 */}act(()=>addArt(round.value,mark))}
function cancel(){pointer=-1;preview.value=null}
onStop(cancel)
function publish(){cancel();if(act(()=>saveArtwork(round.value)))feedback.value='作品已保存在本机小画廊，可以继续创作或导出图片。';else feedback.value=round.value.marks.length?'这幅作品已经保存过了，继续画一点再保存。':'先画一笔或盖一个印章，再保存作品。'}
function rename(event:Event){const title=(event.target as HTMLInputElement).value.trim().slice(0,40)||'我的小世界';if(title===round.value.title)return;act(()=>{round.value.title=title;round.value.revision++;round.value.finished=false;return true})}
async function exportImage(){const svg=picture.value?.element;if(!svg || exporting.value || !round.value.marks.length)return;exporting.value=true;let url='';try{const copy=svg.cloneNode(true) as SVGSVGElement;copy.setAttribute('width','1200');copy.setAttribute('height','800');url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'}));const image=new Image();await new Promise<void>((resolve,reject)=>{image.onload=()=>resolve();image.onerror=()=>reject(new Error('图片绘制失败'));image.src=url});const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=800;const context=canvas.getContext('2d');if(!context)throw new Error('无法导出');context.drawImage(image,0,0);const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('无法生成图片')),'image/png'));const download=URL.createObjectURL(blob),link=document.createElement('a');link.href=download;link.download=round.value.title+'.png';link.click();setTimeout(()=>URL.revokeObjectURL(download),1000);feedback.value='图片已导出，尺寸为 1200 × 800。'}catch{feedback.value='图片暂时无法导出，画作仍保存在本机，可以稍后重试。'}finally{if(url)URL.revokeObjectURL(url);exporting.value=false}}
</script>
<template>
  <ExploreFrame v-bind="frame" creative :progress="`${round.marks.length} 笔 · 自由创作`" :rules="rules" @difficulty="requestReset" @undo="undo" @restart="requestReset()" @reset="reset" @cancel="resetOpen=false" @hint="hint('试着画一片天空，盖几朵云和一棵树，再用不同颜色添上花朵。颜色和布局都由你决定。')">
    <div class="art-inspiration"><label>没有灵感时，选一个创作主题<select aria-label="创作主题" @change="rename($event)"><option v-for="title in artInspirations" :key="title" :selected="round.title===title">{{ title }}</option></select></label><p>主题只是一个起点，画出自己的想法。</p></div><div class="art-title"><span>🎨 小小创作台</span><input :value="round.title" maxlength="40" aria-label="作品名称" @change="rename"></div>
    <div class="explore-toolbar"><button :class="{selected:tool==='brush'}" @click="tool='brush'">✏️ 画笔</button><button :class="{selected:tool==='eraser'}" @click="tool='eraser'">橡皮擦</button><button v-for="stamp in artStamps" :key="stamp.id" :class="{selected:tool===stamp.id}" :aria-label="'选择'+stamp.name+'印章'" @click="tool=stamp.id">{{ stamp.icon }} {{ stamp.name }}</button></div>
    <div class="art-palette"><button v-for="(ink,index) in artColors" :key="ink" :style="{background:ink}" :class="{selected:color===ink}" :aria-label="`画笔颜色 ${index+1}`" :aria-pressed="color===ink" @click="color=ink" /><label>粗细 <input v-model.number="width" type="range" min="2" max="24" aria-label="画笔粗细"></label></div>
    <div class="art-paper"><ArtPicture ref="picture" :marks="round.marks" :background="round.background" :preview="preview" @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="cancel" @lostpointercapture="cancel" /></div>
    <div class="explore-toolbar art-backgrounds"><button v-for="background in artBackgrounds" :key="background.id" :class="{selected:round.background===background.id}" @click="act(()=>setArtBackground(round,background.id))">{{ background.name }}</button></div>
    <div class="art-actions"><button class="explore-primary" :disabled="!round.marks.length" @click="publish">保存作品</button><button class="explore-secondary" :disabled="!round.marks.length || exporting" @click="exportImage">{{ exporting?'正在导出…':'导出图片' }}</button></div>
    <p class="explore-caption">拖动画笔，点一下盖印章；画错了可以撤回，或用橡皮擦点选一笔删除。</p>
    <section v-if="round.gallery.length" class="art-gallery" aria-label="本机小画廊"><h2 class="explore-subheading">本机小画廊 <small>最近 12 幅</small></h2><div><button v-for="(work,index) in round.gallery" :key="index" :aria-label="`继续画作 ${work.title}`" @click="act(()=>loadArtwork(round,index))"><ArtPicture :marks="work.marks" :background="work.background" :title="work.title" /><span>{{ work.title }}</span></button></div></section>
  </ExploreFrame>
</template>
<style scoped>
.art-inspiration{padding:15px;margin-bottom:18px;background:#fff8e5;border:1px solid #e8dfbd;border-radius:10px;color:#8c805e;font-size:11px}.art-inspiration select{display:block;margin-top:9px;width:100%;padding:9px 12px;background:white;border:1px solid #ded6bc;border-radius:7px}.art-inspiration p{margin-top:9px}

.art-title{display:flex;align-items:center;gap:16px;justify-content:space-between;margin:0 0 20px;font-size:12px;color:#9b927a}.art-title input{max-width:60%;padding:9px 12px;border:1px solid #d6e0ca;background:#fffdf5;border-radius:8px;font-size:12px;color:#77856b;text-align:right}.art-palette{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:18px}.art-palette button{width:29px;height:29px;border-radius:50%;border:2px solid #fff;box-shadow:0 0 0 1px #d6dfcc}.art-palette button.selected{box-shadow:0 0 0 3px #b8a071}.art-palette label{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:11px;color:#8b957a}.art-palette input{width:92px;accent-color:#91a885}.art-paper{border:1px solid #d6decb;border-radius:12px;overflow:hidden;background:#fffdf3;box-shadow:0 6px 13px #45612a0a}.art-paper :deep(svg){touch-action:none;cursor:crosshair;user-select:none}.art-backgrounds{justify-content:center;margin:20px 0}.art-actions{display:flex;gap:10px;justify-content:center}.art-gallery h2{display:flex;justify-content:space-between;gap:8px}.art-gallery h2 small{font-size:10px;font-weight:400;color:#9ca58c}.art-gallery>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.art-gallery button{background:white;border:1px solid #dce6d1;border-radius:10px;overflow:hidden}.art-gallery button>span{display:block;font-size:11px;color:#829173;padding:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media(max-width:560px){.art-title{font-size:11px}.art-title input{font-size:11px}.art-palette{gap:8px}.art-palette label{width:100%;margin:7px 0 0}.art-gallery>div{gap:8px}.art-gallery button>span{font-size:10px;padding:8px}.art-actions{gap:8px}}
</style>
